const align4 = (buffer, fill = 0) =>
  buffer.length % 4
    ? Buffer.concat([buffer, Buffer.alloc(4 - (buffer.length % 4), fill)])
    : buffer;

/**
 * Writes a GLB with one named node per part. Materials have only PBR factors
 * (base colour, metalness, roughness) and NO textures: textures cannot be
 * generated by code (SGRAI Sprint 2 slide 13), so the layout JSON supplies
 * the texture set of each element through its `material` (usWEB06 BR 18).
 *
 * @param {{name: string,
 *          parts: {name: string, mesh: import('./geometry.js').MeshData, material: string}[],
 *          materials: Record<string, {colour: number[], metallic: number, roughness: number}>}} model
 */
export function buildGlb({ name, parts, materials }) {
  const chunks = [];
  const bufferViews = [];
  const accessors = [];
  let offset = 0;
  const addView = (data, target) => {
    const padded = align4(data);
    bufferViews.push({
      buffer: 0,
      byteOffset: offset,
      byteLength: data.length,
      ...(target ? { target } : {}),
    });
    chunks.push(padded);
    offset += padded.length;
    return bufferViews.length - 1;
  };

  const materialNames = Object.keys(materials);
  const gltfMaterials = materialNames.map((key) => {
    const { colour, metallic, roughness } = materials[key];
    return {
      name: key,
      pbrMetallicRoughness: {
        baseColorFactor: [...colour.map((value) => value / 255), 1],
        metallicFactor: metallic,
        roughnessFactor: roughness,
      },
    };
  });

  const meshes = parts.map(({ name: partName, mesh, material }) => {
    const materialIndex = materialNames.indexOf(material);
    if (materialIndex < 0) throw new Error(`Unknown material ${material}`);
    const { min, max } = mesh.bounds();
    const count = mesh.positions.length / 3;
    const view = (array, target) => addView(Buffer.from(array.buffer), target);
    accessors.push(
      {
        bufferView: view(new Float32Array(mesh.positions), 34962),
        componentType: 5126,
        count,
        type: 'VEC3',
        min,
        max,
      },
      {
        bufferView: view(new Float32Array(mesh.normals), 34962),
        componentType: 5126,
        count,
        type: 'VEC3',
      },
      {
        bufferView: view(new Float32Array(mesh.uvs), 34962),
        componentType: 5126,
        count,
        type: 'VEC2',
      },
      {
        bufferView: view(new Uint16Array(mesh.indices), 34963),
        componentType: 5123,
        count: mesh.indices.length,
        type: 'SCALAR',
      },
    );
    const first = accessors.length - 4;
    return {
      name: partName,
      primitives: [
        {
          attributes: {
            POSITION: first,
            NORMAL: first + 1,
            TEXCOORD_0: first + 2,
          },
          indices: first + 3,
          material: materialIndex,
        },
      ],
    };
  });

  const binary = Buffer.concat(chunks);
  const gltf = {
    asset: { version: '2.0', generator: 'LaPrizza kitchen models (VIS02)' },
    scene: 0,
    scenes: [{ name, nodes: parts.map((_, index) => index) }],
    nodes: parts.map(({ name: partName }, index) => ({
      name: partName,
      mesh: index,
    })),
    meshes,
    materials: gltfMaterials,
    buffers: [{ byteLength: binary.length }],
    bufferViews,
    accessors,
  };
  const json = align4(Buffer.from(JSON.stringify(gltf), 'utf8'), 0x20);
  const header = Buffer.alloc(12);
  header.writeUInt32LE(0x46546c67, 0);
  header.writeUInt32LE(2, 4);
  header.writeUInt32LE(12 + 8 + json.length + 8 + binary.length, 8);
  const jsonHeader = Buffer.alloc(8);
  jsonHeader.writeUInt32LE(json.length, 0);
  jsonHeader.writeUInt32LE(0x4e4f534a, 4);
  const binHeader = Buffer.alloc(8);
  binHeader.writeUInt32LE(binary.length, 0);
  binHeader.writeUInt32LE(0x004e4942, 4);
  return Buffer.concat([header, jsonHeader, json, binHeader, binary]);
}